import{_ as d,o as e,c as a,a2 as r}from"./chunks/framework.Bg-Zxr5O.js";const u=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"manual-zh/WEIGHT.md","filePath":"manual-zh/WEIGHT.md","lastUpdated":1785684581000}'),s={name:"manual-zh/WEIGHT.md"};function o(n,t,c,i,h,p){return e(),a("div",null,[...t[0]||(t[0]=[r(`<h3 id="_13-7-weight" tabindex="-1">13.7 WEIGHT <a class="header-anchor" href="#_13-7-weight" aria-label="Permalink to &quot;13.7 WEIGHT&quot;">​</a></h3><pre><code>WEIGHT BY var_name.
WEIGHT OFF.
</code></pre><p><code>WEIGHT</code> 为个案赋予不同的权重，改变活动数据集的频数分布。<code>WEIGHT</code> 的执行会延迟到数据被读取之后。</p><p>如果指定了变量名，<code>WEIGHT</code> 会使该变量的值被用作后续统计过程的加权因子。关键字 <code>BY</code> 的使用可选但推荐。加权变量必须为数值型。临时变量不可用于加权（见 <a href="./Scratch-Variables">临时变量</a>）。</p><p>指定 <code>OFF</code> 时，后续统计过程对所有个案赋予相等的权重。</p><p>对个案赋予正整数权重 w，其统计输出与将该个案复制 w 次相同。加权因子为 0 在统计上被视为该个案不存在于输入中。加权值不必为整数，但加权变量的负值和系统缺失值在统计上被解释为加权因子 0。用户缺失值不作特殊对待。</p><p>当 <code>WEIGHT</code> 在 <code>TEMPORARY</code> 之后指定时，它只影响下一个过程（见 <a href="./TEMPORARY">TEMPORARY</a>）。</p><p><code>WEIGHT</code> 不会导致活动数据集中的个案在内存中被复制。</p><h4 id="_13-7-1-权重示例" tabindex="-1">13.7.1 权重示例 <a class="header-anchor" href="#_13-7-1-权重示例" aria-label="Permalink to &quot;13.7.1 权重示例&quot;">​</a></h4><p>可以定义一个包含库存物品清单的数据集。用字符串变量表示物品的描述，用数值变量表示库存数量，是合理的做法，如示例 13.5 所示。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>data list notable list /item (a16) quantity (f8.0). begin   data nuts    345 screws  10034 washers 32012 bolts   876 end data.  echo &#39;Unweighted frequency table&#39;. frequencies /variables = item /format=dfreq.  weight by quantity.  echo &#39;Weighted frequency table&#39;. frequencies /variables = item /format=dfreq.</span></span></code></pre></div><p><strong>示例 13.5：</strong> 对变量 <strong>quantity</strong> 设置权重</p><p>最令人感兴趣的分析之一，很可能是每种库存物品的相对数量。但是，如果不设置权重变量，<code>FREQUENCIES</code>（见 <a href="./FREQUENCIES">FREQUENCIES</a>）无法告诉我们想要了解的信息，因为每种库存物品只有一个个案。示例 13.6 展示了加权与未加权的频数表之间的差异。</p><table tabindex="0"><thead><tr><th></th><th></th><th>频数</th><th>百分比</th><th>有效百分比</th><th>累积百分比</th></tr></thead><tbody><tr><td>有效</td><td>bolts</td><td>1</td><td>25.0%</td><td>25.0%</td><td>25.0%</td></tr><tr><td>nuts</td><td>1</td><td>25.0%</td><td>25.0%</td><td>50.0%</td><td></td></tr><tr><td>screws</td><td>1</td><td>25.0%</td><td>25.0%</td><td>75.0%</td><td></td></tr><tr><td>washers</td><td>1</td><td>25.0%</td><td>25.0%</td><td>100.0%</td><td></td></tr><tr><td>合计</td><td>4</td><td>100.0%</td><td></td><td></td><td></td></tr><tr><td></td><td></td><td>频数</td><td>百分比</td><td>有效百分比</td><td>累积百分比</td></tr><tr><td>有效</td><td>washers</td><td>32012</td><td>74.0%</td><td>74.0%</td><td>74.0%</td></tr><tr><td>screws</td><td>10034</td><td>23.2%</td><td>23.2%</td><td>97.2%</td><td></td></tr><tr><td>bolts</td><td>876</td><td>2.0%</td><td>2.0%</td><td>99.2%</td><td></td></tr><tr><td>nuts</td><td>345</td><td>.8%</td><td>.8%</td><td>100.0%</td><td></td></tr><tr><td>合计</td><td>43267</td><td>100.0%</td><td></td><td></td><td></td></tr></tbody></table><p><strong>示例 13.6：</strong> <strong>items</strong> 的加权与未加权频数表</p>`,15)])])}const E=d(s,[["render",o]]);export{u as __pageData,E as default};
